<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Accessor\DcrInitialAccessTokenExpiresAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the DcrInitialAccessTokenExpiresAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withExpiresAt,
 * getExpiresAt/expiresAt accessors, and isExpiresAtChanged with/without original.
 */
class DcrInitialAccessTokenExpiresAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withExpiresAt creates a new instance with the ExpiresAt set
     * from a string value, and getExpiresAt returns the primitive string.
     */
    public function testWithExpiresAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenExpiresAtAccessorUnitTest();

        // Act
        $result = $holder->withExpiresAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getExpiresAt());
    }
    /**
     * Asserts that withexpiresAt has access to the value object
     * from a string value, and getExpiresAt returns the primitive string.
     */
    public function testWithExpiresAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenExpiresAtAccessorUnitTest();

        // Act
        $result = $holder->withExpiresAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->expiresAt()->value());
    }
    public function testChangedExpiresAt(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenExpiresAtAccessorUnitTest()->withExpiresAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $original = $holder->withExpiresAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withExpiresAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withExpiresAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $withSame = $original->isExpiresAtChanged($same);
        $withDiferent = $original->isExpiresAtChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithDcrInitialAccessTokenExpiresAtAccessorUnitTest
{
    use DcrInitialAccessTokenExpiresAtAccessor;
}
